	if decisionBefore.Kind == "review_cap" && parsed.Positionals[1] == "final-fix" {
		grant, err := db.ReviewCapGrant(ctx.Context, decisionBefore.TaskID)
		if err == nil && grant.DecisionID != id {
			return axi.Failure("review_final_fix_spent", "the one final repair and Review allowance belongs to another Decision", false, "Choose `accept-head` or `rethink` instead")
		}
		if err != nil && !store.IsNotFound(err) {
			return err
		}
	}
	if reason := strings.TrimSpace(parsed.Flags["lead-reason"]); reason != "" {
		cfg, cfgErr := config.Load(home, project.Name)
		task, taskErr := db.TaskByID(ctx.Context, project.ID, decisionBefore.TaskID)
		if role != "lead" || decisionBefore.Kind != "review_cap" || cfgErr != nil || !cfg.Autonomy.Yolo || taskErr != nil {
			return axi.Failure("decision_refused", "--lead-reason is only available to a Lead for a review_cap Decision under delegated review autonomy", false)
		}
		_, expected, valid := parseReviewCapOrigin(decisionBefore.Origin)
		binding, err := currentReviewCapHead(ctx.Context, db, project, task)
		if err != nil {
			return err
		}
		if !valid || binding.Head != expected {
			return axi.Failure("decision_refused", "Review-cap head changed; refresh Decisions before selecting an outcome", false)
		}
		decision, err := db.AnswerDecisionAs(ctx.Context, project.ID, id, parsed.Positionals[1], "lead", "", reason)
		if err != nil {
			return axi.Failure("decision_refused", err.Error(), false, "Run `posse decisions` to inspect valid options")
		}
		if err := s.deliverNotices(ctx.Context, db, project); err != nil && !isHerdrUnavailable(err) {
			return err
		}
		return ctx.Print(axi.Object{{Key: "decision", Value: decisionOutput(ctx.Context, db, project.ID, decision)}, {Key: "help", Value: []any{"The Lead's review-cap choice is recorded with its reason and exact-head binding"}}})
	}
	if decisionBefore.Kind == "teardown_dependants" && parsed.Positionals[1] == "re-point" {
		replacementID := strings.TrimSpace(parsed.Flags["to"])
		if replacementID == "" {
			return axi.Failure("decision_refused", "re-point requires a replacement Task ID", false, "Pass `--to tN`")
		}
		replacement, err := db.Task(ctx.Context, project.ID, replacementID)
		if err != nil {
			return axi.Failure("decision_refused", "replacement Task does not exist in this Project", false)
		}
		if err := validateTeardownRepoint(ctx.Context, db, project, decisionBefore, replacement); err != nil {
			return axi.Failure("decision_refused", err.Error(), false)
		}
	}
	if _, supplied := parsed.Flags["to"]; supplied && (decisionBefore.Kind != "teardown_dependants" || parsed.Positionals[1] != "re-point") {
		return axi.Usage("--to is available only with re-point on a teardown_dependants Decision")
	}
	if role == "lead" && strings.TrimSpace(quote) == "" {
		return axi.Failure("user_only", "only the User answers a Decision; the Lead must quote the User", false, "Pass `--user-approved \"<User's words>\"` after the User answers")
	}
	if quote == "" {
		quote = parsed.Positionals[1]
	} // User's own shell input is their quote.
	reason := ""
	if decisionBefore.Kind == "teardown_dependants" && parsed.Positionals[1] == "re-point" {
		reason = "to=" + parsed.Flags["to"]
	}
	decision, err := db.AnswerDecisionAs(ctx.Context, project.ID, id, parsed.Positionals[1], "user", quote, reason)
	if store.IsNotFound(err) {
		return axi.Failure("decision_unknown", "Decision not found in this Project", false, "Run `posse decisions` to list pending Decisions")
	}
	if err != nil {
		return axi.Failure("decision_refused", err.Error(), false, "Run `posse decisions` to inspect valid options")
	}
	if err := s.deliverNotices(ctx.Context, db, project); err != nil && !isHerdrUnavailable(err) {
		return err
	}
	return ctx.Print(axi.Object{{Key: "decision", Value: decisionOutput(ctx.Context, db, project.ID, decision)}, {Key: "help", Value: []any{"The Lead will receive a Notice to carry out the chosen action"}}})
}

