func (db *DB) UnmetTaskDependencies(ctx context.Context, projectID int64, dependencies []dispatch.Dependency) ([]string, error) {
	unmet := make([]string, 0)
	for _, dependency := range dependencies {
		var predecessorID int64
		var state State
		var mergedRef, reportDigest string
		if err := db.QueryRowContext(ctx, `SELECT id,state,landed_ref,report_digest FROM tasks WHERE project_id=? AND seq=?`, projectID, mustTaskSequence(dependency.TaskID)).Scan(&predecessorID, &state, &mergedRef, &reportDigest); err != nil {
			return nil, fmt.Errorf("unknown Task prerequisite %s", dependency.TaskID)
		}
		ready := false
		switch dependency.Milestone {
		case "reported":
			ready = state == StateReported && reportDigest != "" || state == StateTornDown && reportDigest != ""
		case "accepted":
			var accepted bool
			if err := db.QueryRowContext(ctx, `SELECT EXISTS(SELECT 1 FROM report_acceptances WHERE report_task_id=?)`, predecessorID).Scan(&accepted); err != nil {
				return nil, err
			}
			ready = accepted
		case "landed":
			ready = state == StateMerged || state == StateTornDown && mergedRef != ""
		}
		if !ready {
			reason := dependency.TaskID + ":" + dependency.Milestone
			if state == StateFailed || state == StateLost || state == StateTornDown {
				reason += " (predecessor " + string(state) + ")"
			}
			unmet = append(unmet, reason)
		}
	}
	return unmet, nil
}

func mustTaskSequence(taskID string) int {
	sequence, _ := strconv.Atoi(strings.TrimPrefix(taskID, "t"))
	return sequence
}

func (db *DB) AcquireSandbox(ctx context.Context, projectID, taskID int64, basePath string) (Sandbox, error) {
	tx, err := db.beginTxWithRetry(ctx)
	if err != nil {
		return Sandbox{}, err
	}
	defer tx.Rollback()
	now := time.Now().UnixMilli()
	var sandbox Sandbox
	err = tx.QueryRowContext(ctx, `UPDATE mounts SET state='held',task_id=?,acquired_at=?,released_at=0 WHERE id=(SELECT id FROM mounts WHERE project_id=? AND state='idle' ORDER BY n LIMIT 1) AND state='idle' RETURNING id,project_id,n,path,state,task_id,acquired_at,released_at`, taskID, now, projectID).Scan(&sandbox.ID, &sandbox.ProjectID, &sandbox.Number, &sandbox.Path, &sandbox.State, &sandbox.TaskID, &sandbox.AcquiredAt, &sandbox.ReleasedAt)
	if errors.Is(err, sql.ErrNoRows) {
		err = tx.QueryRowContext(ctx, `INSERT INTO mounts(project_id,n,path,state,task_id,acquired_at,released_at) SELECT ?,COALESCE(MAX(n),0)+1,? || '/sandbox-' || (COALESCE(MAX(n),0)+1),'held',?,?,0 FROM mounts WHERE project_id=? RETURNING id,project_id,n,path,state,task_id,acquired_at,released_at`, projectID, basePath, taskID, now, projectID).Scan(&sandbox.ID, &sandbox.ProjectID, &sandbox.Number, &sandbox.Path, &sandbox.State, &sandbox.TaskID, &sandbox.AcquiredAt, &sandbox.ReleasedAt)
	}
	if err != nil {
		return Sandbox{}, err
	}
	if _, err := tx.ExecContext(ctx, `UPDATE tasks SET mount_id=?,worktree_path=?,updated_at=? WHERE id=?`, sandbox.ID, sandbox.Path, now, taskID); err != nil {
		return Sandbox{}, err
	}
	if err := tx.Commit(); err != nil {
		return Sandbox{}, err
	}
	if err := db.PersistTask(ctx, taskID); err != nil {
		return Sandbox{}, err
	}
	return sandbox, nil
}

