+	for seq := 1; seq <= 2; seq++ {
+		plan := basePlan.Bind(fmt.Sprintf("t%d", seq))
+		data, err := plan.Encode()
+		if err != nil {
+			t.Fatal(err)
+		}
+		taskID, err := db.CreateTask(ctx, project.ID, Task{Seq: seq, Type: "change", Title: fmt.Sprintf("Task %d", seq), State: StateQueued, PlanJSON: data})
