100: func validateTeardownRepoint(ctx context.Context, db *store.DB, project store.Project, decision store.Decision, replacement store.Task) error {
101: 	predecessor, dependants, err := teardownDecisionDependants(ctx, db, project, decision)
102: 	if err != nil {
103: 		return err
104: 	}
105: 	if replacement.ID == predecessor.ID {
106: 		return fmt.Errorf("replacement Task must differ from the torn-down predecessor")
107: 	}
108: 	for _, dependant := range dependants {
109: 		plan, err := dependant.AdmittedPlan()
110: 		if err != nil {
111: 			return admittedPlanFailure(err)
112: 		}
113: 		for _, dependency := range plan.Dependencies {
114: 			if dependency.TaskID != taskIDString(predecessor.Seq) {
115: 				continue
116: 			}
117: 			if replacement.Seq >= dependant.Seq {
118: 				return fmt.Errorf("replacement Task %s must precede dependant %s", taskIDString(replacement.Seq), taskIDString(dependant.Seq))
119: 			}
120: 			validType := dependency.Milestone == "landed" && replacement.Type == "change" || dependency.Milestone == "reported" && (replacement.Type == "research" || replacement.Type == "review") || dependency.Milestone == "accepted" && replacement.Type == "research" && (replacement.ReportKind == "spec" || replacement.ReportKind == "tickets")
121: 			if !validType {
122: 				return fmt.Errorf("replacement Task %s cannot satisfy %s", taskIDString(replacement.Seq), dependency.Milestone)
123: 			}
124: 		}
125: 	}
126: 	return nil
127: }
