129: func (s *Service) applyTeardownDependantsDecision(ctx context.Context, db *store.DB, project store.Project, cfg config.Config, decision store.Decision) error {
130: 	predecessor, dependants, err := teardownDecisionDependants(ctx, db, project, decision)
131: 	if err != nil {
132: 		return err
133: 	}
134: 	if len(dependants) == 0 {
135: 		return nil
136: 	}
137: 	if decision.Answer == "cascade" {
138: 		for _, dependant := range dependants {
139: 			if err := db.Transition(ctx, dependant.ID, store.StateQueued, store.StateTornDown, "cli", "Cascade teardown approved for predecessor "+taskIDString(predecessor.Seq)); err != nil && err != store.ErrStateRace {
140: 				return err
141: 			}
142: 			if err := db.ObsoleteTaskDecisions(ctx, dependant.ID); err != nil {
143: 				return err
144: 			}
145: 		}
146: 		return nil
147: 	}
148: 	if decision.Answer != "re-point" || !strings.HasPrefix(decision.AnswerReason, "to=") {
149: 		return fmt.Errorf("re-point requires a replacement Task ID")
150: 	}
151: 	replacementID := strings.TrimPrefix(decision.AnswerReason, "to=")
152: 	replacement, err := db.Task(ctx, project.ID, replacementID)
153: 	if err != nil {
154: 		return fmt.Errorf("replacement Task %s does not exist", replacementID)
155: 	}
156: 	if err := validateTeardownRepoint(ctx, db, project, decision, replacement); err != nil {
157: 		return err
158: 	}
159: 	updates := make([]store.TaskPlanRevision, 0, len(dependants))
160: 	for _, dependant := range dependants {
161: 		plan, err := dependant.AdmittedPlan()
162: 		if err != nil {
163: 			return admittedPlanFailure(err)
164: 		}
165: 		if plan == nil {
166: 			return fmt.Errorf("queued dependant %s has no admitted plan", taskIDString(dependant.Seq))
167: 		}
168: 		revised := *plan
169: 		for _, dependency := range plan.Dependencies {
170: 			if dependency.TaskID != taskIDString(predecessor.Seq) {
171: 				continue
172: 			}
173: 			revised, err = revised.RepointDependency(dependency.TaskID, taskIDString(replacement.Seq), dependency.Milestone)
174: 			if err != nil {
175: 				return err
176: 			}
177: 		}
178: 		updates = append(updates, store.TaskPlanRevision{Task: dependant, Plan: revised})
179: 	}
180: 	if err := db.ReviseTaskPlans(ctx, updates); err != nil {
181: 		return err
182: 	}
183: 	_, err = s.refillQueuedTasks(ctx, db, project, cfg, false)
184: 	return err
185: }
